/**
 * Geometry shared by the donor map and its regression tests.
 *
 * The land silhouette was generated from Natural Earth 1:110m land data via
 * `world-atlas@2.0.2`, projected with an equirectangular projection into this
 * 1000 × 500 viewBox, rounded to whole SVG units, and simplified for a landing
 * page-sized illustration. Natural Earth data is public domain:
 * https://www.naturalearthdata.com/about/terms-of-use/
 *
 * Keeping the resulting path local avoids a runtime map request and ensures the
 * coastline and the donor coordinates always use the exact same projection.
 */
export const WORLD_MAP_WIDTH = 1000;
export const WORLD_MAP_HEIGHT = 500;

export function projectLongitude(lng: number): number {
  return ((lng + 180) / 360) * WORLD_MAP_WIDTH;
}

export function projectLatitude(lat: number): number {
  return ((90 - lat) / 180) * WORLD_MAP_HEIGHT;
}

export interface MapLabelInput {
  id: string;
  label: string;
  x: number;
  y: number;
}

export interface MapLabelPlacement extends MapLabelInput {
  labelX: number;
  labelY: number;
  anchor: "start" | "middle" | "end";
}

const LABEL_CANDIDATES: Array<{ dx: number; dy: number; anchor: MapLabelPlacement["anchor"] }> = [
  { dx: 0, dy: -18, anchor: "middle" },
  { dx: 14, dy: -10, anchor: "start" },
  { dx: -14, dy: -10, anchor: "end" },
  { dx: 0, dy: 30, anchor: "middle" },
  { dx: 14, dy: 25, anchor: "start" },
  { dx: -14, dy: 25, anchor: "end" },
];

type LabelBox = { left: number; right: number; top: number; bottom: number };

/** Place desktop labels deterministically without letting nearby cities overlap. */
export function layoutMapLabels(inputs: MapLabelInput[]): MapLabelPlacement[] {
  const boxes: LabelBox[] = [];
  const byId = new Map<string, MapLabelPlacement>();
  const ordered = [...inputs].sort((a, b) => a.y - b.y || a.x - b.x || a.id.localeCompare(b.id));

  for (const input of ordered) {
    const width = Math.max(42, Math.min(128, Array.from(input.label).length * 8.5 + 12));
    let selected: { placement: MapLabelPlacement; box: LabelBox } | null = null;

    for (const candidate of LABEL_CANDIDATES) {
      const rawX = input.x + candidate.dx;
      const half = candidate.anchor === "middle" ? width / 2 : 0;
      const minX = candidate.anchor === "end" ? width + 8 : candidate.anchor === "middle" ? half + 8 : 8;
      const maxX = candidate.anchor === "start"
        ? WORLD_MAP_WIDTH - width - 8
        : candidate.anchor === "middle"
          ? WORLD_MAP_WIDTH - half - 8
          : WORLD_MAP_WIDTH - 8;
      const labelX = Math.max(minX, Math.min(maxX, rawX));
      const labelY = Math.max(20, Math.min(WORLD_MAP_HEIGHT - 10, input.y + candidate.dy));
      const left = candidate.anchor === "start" ? labelX : candidate.anchor === "end" ? labelX - width : labelX - half;
      const box = { left, right: left + width, top: labelY - 16, bottom: labelY + 5 };
      const overlaps = boxes.some(
        (other) => box.left < other.right + 6 && box.right + 6 > other.left && box.top < other.bottom + 5 && box.bottom + 5 > other.top
      );
      selected = { placement: { ...input, labelX, labelY, anchor: candidate.anchor }, box };
      if (!overlaps) break;
    }

    if (selected) {
      boxes.push(selected.box);
      byId.set(input.id, selected.placement);
    }
  }

  return inputs.flatMap((input) => {
    const placement = byId.get(input.id);
    return placement ? [placement] : [];
  });
}

